reference_pwsh:
$py = if ($IsWindows) { 'python' } else { 'python3' }
$p0 = Start-Process $py -ArgumentList 'tools/check.py','web' -PassThru -NoNewWindow -RedirectStandardOutput ([IO.Path]::GetTempFileName())
$p1 = Start-Process $py -ArgumentList 'tools/check.py','api' -PassThru -NoNewWindow -RedirectStandardOutput ([IO.Path]::GetTempFileName())
$p2 = Start-Process $py -ArgumentList 'tools/check.py','db' -PassThru -NoNewWindow -RedirectStandardOutput ([IO.Path]::GetTempFileName())
$p0.WaitForExit(); if ($p0.ExitCode -ne 0) { 'web failed' }
$p1.WaitForExit(); if ($p1.ExitCode -ne 0) { 'api failed' }
$p2.WaitForExit(); if ($p2.ExitCode -ne 0) { 'db failed' }
